import { Text, View } from 'react-native'
import { WebView } from 'react-native-webview'
import { StatusBar } from 'expo-status-bar'
import { DevServerUrls } from '@/utils/hooks/useDevServerUrl'
import { useState, useEffect, useRef } from 'react'
import { AnimatePresence, MotiView } from 'moti'
import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { pathChangeEmitter, PathChangeEvents } from '@/utils'
const LOADING_DELAY_AFTER_LOAD = 500

const Dot = ({ index, size = 20 }: { index: number; size?: number }) => {
	const { theme } = useTheme()

	return (
		<MotiView
			from={{ opacity: 0.35, scale: 0.8 }}
			animate={{ opacity: 1, scale: 1 }}
			transition={{
				type: 'timing',
				duration: 500,
				delay: index * 180,
				repeat: Infinity,
				repeatReverse: true
			}}
			style={{
				width: size,
				height: size,
				borderRadius: size / 2,
				backgroundColor: colors[theme].gray[900]
			}}
		/>
	)
}

export const WebViewScreen = ({
	devServerUrls,
	mode
}: {
	devServerUrls: DevServerUrls | null
	mode: 'web' | 'mobile' | null
}) => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()

	const [webViewIsLoading, setWebViewIsLoading] = useState(true)
	const [path, setPath] = useState('')
	const previousModeRef = useRef<'web' | 'mobile' | null>(mode)

	useEffect(() => {
		if (previousModeRef.current !== mode && mode !== null) {
			setWebViewIsLoading(true)
			previousModeRef.current = mode
		}
	}, [mode])

	const handleWebViewLoaded = () => {
		setTimeout(() => {
			setWebViewIsLoading(false)
		}, LOADING_DELAY_AFTER_LOAD)
	}

	useEffect(() => {
		const handlePathChange = ({ path }: { path: string }) => {
			setPath(path)
		}

		pathChangeEmitter.on(PathChangeEvents.PATH_CHANGE, handlePathChange)

		return () => {
			pathChangeEmitter.off(PathChangeEvents.PATH_CHANGE, handlePathChange)
		}
	}, [])

	return (
		<>
			<StatusBar style="auto" />
			<AnimatePresence>
				{(webViewIsLoading || !mode) && (
					<MotiView
						from={{ opacity: 1 }}
						animate={{ opacity: 1 }}
						exit={{ opacity: 0 }}
						style={styles.loadingContainer(theme)}
					>
						<View style={styles.dotsContainer}>
							<Dot index={0} />
							<Dot index={1} />
							<Dot index={2} />
						</View>
						<Text style={styles.loadingText(theme)}> Loading...</Text>
					</MotiView>
				)}
			</AnimatePresence>
			{devServerUrls && mode && (
				<WebView
					style={[
						styles.webView,
						{ paddingTop: insets.top, paddingBottom: insets.bottom }
					]}
					source={{
						uri:
							mode === 'mobile'
								? `${devServerUrls.mobile}${path}`
								: `${devServerUrls.web}${path}`
					}}
					onLoadEnd={handleWebViewLoaded}
				/>
			)}
		</>
	)
}

const styles = defineStyles({
	loadingContainer: (theme: Theme) => ({
		zIndex: 1,
		flex: 1,
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		justifyContent: 'center',
		alignItems: 'center',
		backgroundColor: colors[theme].background,
		gap: 28
	}),
	loadingText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '600',
		color: colors[theme].gray[900]
	}),
	dotsContainer: {
		flexDirection: 'row',
		gap: 20
	},
	webView: {
		flex: 1,
		height: '100%',
		width: '100%'
	}
})
